{
  "segments": [
    {
      "text": "Doctor Lin, whose full name was Lin Lan, met Sam at the gate.",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "You are early,",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "Dr. Lin said.",
      "kind": "narration",
      "speaker": "UNKNOWN"
    },
    {
      "text": "Sam put down his bag. ",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "The bus was quick today,",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "he replied.",
      "kind": "narration",
      "speaker": "UNKNOWN"
    },
    {
      "text": "Lin Lan checked her watch. ",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "We still have ten minutes,",
      "kind": "narration",
      "speaker": "NARRATOR"
    },
    {
      "text": "she said.",
      "kind": "narration",
      "speaker": "UNKNOWN"
    }
  ]
}
